function buildWorkBoard(commands) {
  if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
  const board = { queued: [], working: [], finished: [] };
  const ids = new Set();
  const markers = { critical: 'red', standard: 'blue', deferred: 'gray' };
  const lanes = new Set(Object.keys(board));
  const requireText = (value, name) => {
    if (typeof value !== 'string' || value.trim() === '') throw new TypeError(name + ' must be non-empty');
    return value.trim();
  };

  for (const command of commands) {
    if (!command || typeof command !== 'object' || Array.isArray(command)) throw new TypeError('invalid command');
    if (command.type === 'add') {
      const id = requireText(command.id, 'id');
      const summary = requireText(command.summary, 'summary');
      if (ids.has(id)) throw new Error('duplicate id');
      if (!Object.prototype.hasOwnProperty.call(markers, command.severity)) throw new TypeError('invalid severity');
      if (!Array.isArray(command.labels) || command.labels.some(label => typeof label !== 'string' || label.trim() === '')) {
        throw new TypeError('labels must be an array of non-empty strings');
      }
      board.queued.push({
        id,
        summary,
        severity: command.severity,
        marker: markers[command.severity],
        labels: command.labels
      });
      ids.add(id);
    } else if (command.type === 'move') {
      const id = requireText(command.id, 'id');
      if (!lanes.has(command.lane)) throw new TypeError('invalid lane');
      let card = null;
      for (const lane of lanes) {
        const index = board[lane].findIndex(item => item.id === id);
        if (index !== -1) card = board[lane].splice(index, 1)[0];
      }
      if (!card) throw new Error('unknown card');
      board[command.lane].push(card);
    } else {
      throw new TypeError('unknown command type');
    }
  }

  return { ...board, queuedCount: board.queued.length };
}

module.exports = { buildWorkBoard };

