'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['buildWorkBoard']);
const { buildWorkBoard } = api;

assert.deepStrictEqual(buildWorkBoard([]), { queued: [], working: [], finished: [], queuedCount: 0 });

const labels = ['backend', 'urgent'];
const commands = [
  { type: 'add', id: 'a', summary: 'Alpha', severity: 'critical', labels },
  { type: 'add', id: 'b', summary: 'Beta', severity: 'standard', labels: [] },
  { type: 'add', id: 'c', summary: 'Gamma', severity: 'deferred', labels: ['later'] },
  { type: 'move', id: 'a', lane: 'working' },
  { type: 'move', id: 'b', lane: 'working' },
  { type: 'move', id: 'a', lane: 'working' },
  { type: 'move', id: 'c', lane: 'finished' }
];
const board = buildWorkBoard(commands);
assert.deepStrictEqual(board, {
  queued: [],
  working: [
    { id: 'b', summary: 'Beta', severity: 'standard', marker: 'blue', labels: [] },
    { id: 'a', summary: 'Alpha', severity: 'critical', marker: 'red', labels: ['backend', 'urgent'] }
  ],
  finished: [
    { id: 'c', summary: 'Gamma', severity: 'deferred', marker: 'gray', labels: ['later'] }
  ],
  queuedCount: 0
});
labels[0] = 'changed';
commands[1].summary = 'changed';
assert.deepStrictEqual(board.working[1].labels, ['backend', 'urgent']);
assert.strictEqual(board.working[0].summary, 'Beta');

const ordering = buildWorkBoard([
  { type: 'add', id: '1', summary: 'One', severity: 'standard', labels: [] },
  { type: 'add', id: '2', summary: 'Two', severity: 'standard', labels: [] },
  { type: 'add', id: '3', summary: 'Three', severity: 'standard', labels: [] },
  { type: 'move', id: '1', lane: 'queued' }
]);
assert.deepStrictEqual(ordering.queued.map(card => card.id), ['2', '3', '1']);
assert.strictEqual(ordering.queuedCount, 3);

const invalidInputs = [
  null,
  {},
  [{ type: 'unknown' }],
  [{ type: 'move', id: 'missing', lane: 'queued' }],
  [{ type: 'add', id: '', summary: 'x', severity: 'standard', labels: [] }],
  [{ type: 'add', id: 'x', summary: '', severity: 'standard', labels: [] }],
  [{ type: 'add', id: 'x', summary: 'x', severity: 'urgent', labels: [] }],
  [{ type: 'add', id: 'x', summary: 'x', severity: 'standard', labels: 'tag' }],
  [{ type: 'add', id: 'x', summary: 'x', severity: 'standard', labels: [''] }],
  [
    { type: 'add', id: 'x', summary: 'x', severity: 'standard', labels: [] },
    { type: 'add', id: 'x', summary: 'again', severity: 'critical', labels: [] }
  ],
  [
    { type: 'add', id: 'x', summary: 'x', severity: 'standard', labels: [] },
    { type: 'move', id: 'x', lane: 'invalid' }
  ]
];
for (const input of invalidInputs) assert.throws(() => buildWorkBoard(input));

